package com.jarvis.core.google;
import com.jarvis.common.integration.IntegrationState;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.*;
import java.net.*;
import java.net.http.HttpClient;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Local HTTP protocol fixture; never contacts Google or reads a real mailbox. */
class GooglePermissionsTest {
 static final String CLIENT="12345678-test.apps.googleusercontent.com",READ="https://www.googleapis.com/auth/gmail.readonly",COMPOSE="https://www.googleapis.com/auth/gmail.compose";
 HttpServer server;GoogleOAuth oauth;ConnectedAccountRepository repository;Map<String,ConnectedAccountRepository.ConnectedAccount> saved=new ConcurrentHashMap<>();AtomicInteger tokenCalls=new AtomicInteger();AtomicReference<String> reply=new AtomicReference<>();AtomicInteger status=new AtomicInteger(200);
 @BeforeEach void setup()throws Exception{
  repository=mock(ConnectedAccountRepository.class);when(repository.find(anyString(),anyString())).thenAnswer(i->Optional.ofNullable(saved.get(i.getArgument(0)+"/"+i.getArgument(1))));doAnswer(i->{String user=i.getArgument(0),provider=i.getArgument(1);saved.put(user+"/"+provider,new ConnectedAccountRepository.ConnectedAccount(user,provider,i.getArgument(2),i.getArgument(3),Instant.now()));return null;}).when(repository).save(anyString(),anyString(),anyString(),anyString());
  server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/token",e->{tokenCalls.incrementAndGet();e.getRequestBody().readAllBytes();String response=reply.get();if(response==null)response="{\"access_token\":\"access-new\",\"expires_in\":3600,\"scope\":\""+READ+"\"}";byte[] b=response.getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(status.get(),b.length);e.getResponseBody().write(b);e.close();});server.start();URI base=URI.create("http://127.0.0.1:"+server.getAddress().getPort());oauth=new GoogleOAuth(HttpClient.newHttpClient(),repository,base.resolve("/authorize"),base.resolve("/token"),base.resolve("/revoke"),"",CLIENT,"fake-test-secret",43822);
 }
 @AfterEach void stop(){server.stop(0);}
 void seed(String user,String scope)throws Exception{repository.save(user,"gmail","",new ObjectMapper().writeValueAsString(Map.of("clientId",CLIENT,"refreshToken","refresh-"+user,"scopesKnown",true,"grantedScopes",List.of(scope))));}
 @Test void permittedReadRefreshesAutomaticallyAndDoesNotNeedConsent()throws Exception{seed("alice",READ);oauth.requireScopes("alice",GoogleService.GMAIL,Set.of(READ));oauth.requireScopes("alice",GoogleService.GMAIL,Set.of(READ));assertThat(tokenCalls).hasValue(1);assertThat(oauth.operationStatus("alice",GoogleService.GMAIL,"READ").state()).isEqualTo(IntegrationState.CONNECTED);}
 @Test void missingReadScopeIsTypedAndNotConfusedWithConnection()throws Exception{seed("alice",COMPOSE);reply.set("{\"access_token\":\"access\",\"scope\":\""+COMPOSE+"\"}");assertThatThrownBy(()->oauth.requireScopes("alice",GoogleService.GMAIL,Set.of(READ))).isInstanceOfSatisfying(GoogleException.class,e->assertThat(e.code()).isEqualTo("MISSING_SCOPE"));assertThat(oauth.operationStatus("alice",GoogleService.GMAIL,"READ").missingScopes()).containsExactly(READ);}
 @Test void alreadyGrantedBroaderScopeCanReadWithoutNewAuthorization()throws Exception{String broader="https://www.googleapis.com/auth/gmail.modify";seed("alice",broader);reply.set("{\"access_token\":\"access\",\"scope\":\""+broader+"\"}");oauth.requireScopes("alice",GoogleService.GMAIL,Set.of(READ));assertThat(tokenCalls).hasValue(1);}
 @Test void refreshWithoutRotatedTokenOrScopePreservesBoth()throws Exception{seed("alice",READ);reply.set("{\"access_token\":\"access\",\"expires_in\":3600}");oauth.requireScopes("alice",GoogleService.GMAIL,Set.of(READ));var secret=new ObjectMapper().readTree(saved.get("alice/gmail").secret());assertThat(secret.path("refreshToken").asText()).isEqualTo("refresh-alice");assertThat(secret.path("grantedScopes").get(0).asText()).isEqualTo(READ);}
 @Test void reauthorizationWithoutRefreshTokenDoesNotEraseExistingToken()throws Exception{seed("alice",READ);var authorization=oauth.begin("alice",GoogleService.GMAIL,Set.of(READ));oauth.complete("alice",authorization,"one-use-code");assertThat(new ObjectMapper().readTree(saved.get("alice/gmail").secret()).path("refreshToken").asText()).isEqualTo("refresh-alice");}
 @Test void requestsOnlyRequiredScopesAndUsesIncrementalConsent()throws Exception{seed("alice",READ);String url=URLDecoder.decode(oauth.begin("alice",GoogleService.GMAIL,Set.of(READ)).url(),StandardCharsets.UTF_8);assertThat(url).contains("include_granted_scopes=true").contains("scope="+READ).doesNotContain(COMPOSE,"prompt=consent");}
 @Test void wrongOwnerCannotCompleteAnotherUsersAuthorization(){var authorization=oauth.begin("alice",GoogleService.GMAIL,Set.of(READ));assertThatThrownBy(()->oauth.complete("bob",authorization,"code")).isInstanceOfSatisfying(GoogleException.class,e->assertThat(e.code()).isEqualTo("AUTHORIZATION_FAILED"));assertThat(tokenCalls).hasValue(0);assertThat(saved).isEmpty();}
 @Test void usersNeverBorrowAnotherUsersTokens()throws Exception{seed("alice",READ);assertThatThrownBy(()->oauth.accessToken("bob",GoogleService.GMAIL,false)).isInstanceOfSatisfying(GoogleException.class,e->assertThat(e.code()).isEqualTo("DISCONNECTED"));assertThat(tokenCalls).hasValue(0);}
 @Test void concurrent401sRefreshOnce()throws Exception{seed("alice",READ);reply.set("{\"access_token\":\"old\",\"expires_in\":3600}");oauth.accessToken("alice",GoogleService.GMAIL,false);reply.set("{\"access_token\":\"new\",\"expires_in\":3600}");try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->oauth.rejectedAccessToken("alice",GoogleService.GMAIL,"old"));var b=pool.submit(()->oauth.rejectedAccessToken("alice",GoogleService.GMAIL,"old"));assertThat(a.get(3,TimeUnit.SECONDS)).isEqualTo("new");assertThat(b.get(3,TimeUnit.SECONDS)).isEqualTo("new");}assertThat(tokenCalls).hasValue(2);}
 @Test void temporaryTokenFailureDoesNotAskForAuthorization()throws Exception{seed("alice",READ);status.set(503);reply.set("{\"error\":\"temporarily_unavailable\"}");assertThatThrownBy(()->oauth.requireScopes("alice",GoogleService.GMAIL,Set.of(READ))).isInstanceOfSatisfying(GoogleException.class,e->{assertThat(e.code()).isEqualTo("TEMPORARILY_UNAVAILABLE");assertThat(e.authorizationRequired()).isFalse();});}
 @Test void disabledApiAndGeneric403AreNotMissingScopes(){assertThat(GoogleApiErrors.failure(403,"{\"error\":{\"errors\":[{\"reason\":\"accessNotConfigured\"}]}}").code()).isEqualTo("API_DISABLED");assertThat(GoogleApiErrors.failure(403,"{}").authorizationRequired()).isFalse();assertThat(GoogleApiErrors.failure(403,"{\"error\":{\"details\":[{\"reason\":\"ACCESS_TOKEN_SCOPE_INSUFFICIENT\"}]}}").code()).isEqualTo("MISSING_SCOPE");}
 @Test void metadataNeverExposesTokens()throws Exception{seed("alice",READ);oauth.requireScopes("alice",GoogleService.GMAIL,Set.of(READ));assertThat(new ObjectMapper().writeValueAsString(oauth.status("alice",GoogleService.GMAIL))).doesNotContain("refresh-alice","access-new","fake-test-secret");}

 @Test void duplicateCallbackNeverExchangesTheCodeTwice()throws Exception{seed("alice",READ);var authorization=oauth.begin("alice",GoogleService.GMAIL,Set.of(READ));oauth.complete("alice",authorization,"code");assertThatThrownBy(()->oauth.complete("alice",authorization,"code")).isInstanceOfSatisfying(GoogleException.class,e->assertThat(e.code()).isEqualTo("AUTHORIZATION_ALREADY_COMPLETED"));assertThat(tokenCalls).hasValue(1);}
 @Test void invalidGrantUpdatesAuthoritativeStateRatherThanLeavingConnected()throws Exception{seed("alice",READ);status.set(400);reply.set("{\"error\":\"invalid_grant\"}");assertThatThrownBy(()->oauth.accessToken("alice",GoogleService.GMAIL,false)).isInstanceOf(GoogleException.class);assertThat(oauth.operationStatus("alice",GoogleService.GMAIL,"READ").state()).isEqualTo(IntegrationState.AUTHORIZATION_REQUIRED);}
}
